import unittest
from candidate import fizz_buzz

class TestFizzBuzz(unittest.TestCase):
    def expected_count(self, n):
        count = 0
        for i in range(n):
            if i % 11 == 0 or i % 13 == 0:
                count += str(i).count('7')
        return count

    def test_zero_input(self):
        self.assertEqual(fizz_buzz(0), 0)

    def test_negative_input(self):
        self.assertEqual(fizz_buzz(-10), 0)

    def test_single_digit_no_multiples(self):
        self.assertEqual(fizz_buzz(7), 0)

    def test_just_divisible_by_11(self):
        self.assertEqual(fizz_buzz(11), 0)

    def test_just_divisible_by_13(self):
        self.assertEqual(fizz_buzz(13), 0)

    def test_multiple_multiples_no_sevens(self):
        self.assertEqual(fizz_buzz(100), self.expected_count(100))

    def test_77_case(self):
        self.assertEqual(fizz_buzz(78), 2)

    def test_78_case_excludes_78(self):
        self.assertEqual(fizz_buzz(78), 2)

    def test_79_case_includes_78(self):
        self.assertEqual(fizz_buzz(79), 3)

    def test_type_error_none(self):
        with self.assertRaises(TypeError):
            fizz_buzz(None)

    def test_type_error_string(self):
        with self.assertRaises(TypeError):
            fizz_buzz('100')

    def test_type_error_float(self):
        with self.assertRaises(TypeError):
            fizz_buzz(10.5)

    def test_type_error_list(self):
        with self.assertRaises(TypeError):
            fizz_buzz([1, 2, 3])

    def test_type_bool_true(self):
        self.assertEqual(fizz_buzz(True), 0)

    def test_type_bool_false(self):
        self.assertEqual(fizz_buzz(False), 0)

    def test_return_type(self):
        self.assertIsInstance(fizz_buzz(50), int)

    def test_large_input_performance(self):
        self.assertEqual(fizz_buzz(10000), self.expected_count(10000))

if __name__ == '__main__':
    unittest.main()
